{
      ok: false,
      code: "LIST_MREAD_STAGING_SESSIONS_FAILED",
      message: error?.message || "Could not load MREAD staging sessions",
      rows: [],
      summary: {
        totalSessions: 0,
      },
    }

{
      ok: false,
      code: "PERMISSION_DENIED",
